/* @autogenerated */
import { Component, inject } from '@angular/core';
import { User } from 'app/features/identity/user/model/user.model';
import { UserRepository } from 'app/features/identity/user/repository/user-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';

@Component({ selector: 'user-view-accept-action', standalone: false, template: '' })
export class UserViewAcceptActionComponent extends ConfirmAction<User> {
  readonly name = 'accept';
  protected readonly scope = 'identity/user';
  protected readonly repository = inject(UserRepository);

  protected override appliesTo(items: User[]) {
    return items.every((item) => item.approvalStatus !== 'accepted');
  }

  protected execute([item]: User[]) {
    return this.repository.accept(item.uid);
  }
}
